//
// Tests for the meal-feedback support-request helpers: category->subject
// mapping, message composition, and the local ledger round-trip. The live
// network calls (fetchMeCore, resolveDeliveryMarketID, submitContactForm)
// are exercised by dogfooding against the real API, not mocked here --
// matching forkable_orders_test.go, which likewise only unit-tests the pure
// payloadMutationErrors helper and leaves mutateGraphQL itself to live
// verification. This is a hand-authored file (no "Generated by ..."
// header) so `generate --force` preserves it, matching meal_feedback.go.

package cli

import (
	"strings"
	"testing"
)

func TestMealFeedbackSubjectFor(t *testing.T) {
	tests := []struct {
		category    string
		wantSubject string
		wantOK      bool
	}{
		{"missing-item", "Missing Meal", true},
		{"wrong-item", "Report Issue", true},
		{"quality", "Report Issue", true},
		{"late", "Delivery Status", true},
		{"other", "General Inquiry", true},
		{"", "", false},
		{"spicy", "", false},
		{"MISSING-ITEM", "", false}, // case handled by the caller (lowercased before this check), not the mapper itself
	}
	for _, tt := range tests {
		gotSubject, gotOK := mealFeedbackSubjectFor(tt.category)
		if gotOK != tt.wantOK || (gotOK && gotSubject != tt.wantSubject) {
			t.Errorf("mealFeedbackSubjectFor(%q) = (%q, %v), want (%q, %v)", tt.category, gotSubject, gotOK, tt.wantSubject, tt.wantOK)
		}
	}
}

func TestComposeMealFeedbackMessage(t *testing.T) {
	tests := []struct {
		name              string
		deliveryID        int64
		note, venue, item string
		pieceID           string
		wantContains      []string
		wantNotContains   []string
	}{
		{
			name:            "note only",
			deliveryID:      12345,
			note:            "Rice was missing",
			wantContains:    []string{"Rice was missing", "Delivery ID: 12345"},
			wantNotContains: []string{"venue:", "item:", "piece:"},
		},
		{
			name:         "full context",
			deliveryID:   12345,
			note:         "Rice was missing",
			venue:        "Example Venue",
			item:         "Example Item",
			pieceID:      "abc-123",
			wantContains: []string{"Rice was missing", "Delivery ID: 12345", "venue: Example Venue", "item: Example Item", "piece: abc-123"},
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := composeMealFeedbackMessage(tt.deliveryID, tt.note, tt.venue, tt.item, tt.pieceID)
			for _, want := range tt.wantContains {
				if !strings.Contains(got, want) {
					t.Errorf("composeMealFeedbackMessage(...) = %q, want substring %q", got, want)
				}
			}
			for _, notWant := range tt.wantNotContains {
				if strings.Contains(got, notWant) {
					t.Errorf("composeMealFeedbackMessage(...) = %q, want NOT to contain %q", got, notWant)
				}
			}
		})
	}
}

// TestAppendAndReadMealFeedback exercises the local ledger append/read
// round-trip against a temp data dir (via FORKABLE_DATA_DIR) so it never
// touches the caller's real ledger.
func TestAppendAndReadMealFeedback(t *testing.T) {
	dir := t.TempDir()
	t.Setenv("FORKABLE_DATA_DIR", dir)

	entries, err := readMealFeedback()
	if err != nil {
		t.Fatalf("readMealFeedback() on empty store = %v, want nil error", err)
	}
	if len(entries) != 0 {
		t.Fatalf("readMealFeedback() on empty store = %d entries, want 0", len(entries))
	}

	first := MealFeedbackEntry{DeliveryID: 11111, Category: "missing-item", Subject: "Missing Meal", Note: "no rice", Submitted: true}
	second := MealFeedbackEntry{DeliveryID: 22222, Category: "wrong-item", Subject: "Report Issue", Note: "wrong bowl", Submitted: false}
	if err := appendMealFeedback(first); err != nil {
		t.Fatalf("appendMealFeedback(first) = %v, want nil", err)
	}
	if err := appendMealFeedback(second); err != nil {
		t.Fatalf("appendMealFeedback(second) = %v, want nil", err)
	}

	entries, err = readMealFeedback()
	if err != nil {
		t.Fatalf("readMealFeedback() after writes = %v, want nil error", err)
	}
	if len(entries) != 2 {
		t.Fatalf("readMealFeedback() after writes = %d entries, want 2", len(entries))
	}
	if entries[0].DeliveryID != first.DeliveryID || !entries[0].Submitted {
		t.Errorf("entries[0] = %+v, want delivery %d / submitted=true", entries[0], first.DeliveryID)
	}
	if entries[1].DeliveryID != second.DeliveryID || entries[1].Submitted {
		t.Errorf("entries[1] = %+v, want delivery %d / submitted=false", entries[1], second.DeliveryID)
	}
}

// TestMealFeedbackNoteTruncation guards the same truncation contract
// feedback.go established for CLI-feedback text, applied here to the
// meal-issue note.
func TestMealFeedbackNoteTruncation(t *testing.T) {
	longNote := strings.Repeat("x", mealFeedbackMaxNoteLen+500)
	truncated := longNote
	if len(truncated) > mealFeedbackMaxNoteLen {
		truncated = truncated[:mealFeedbackMaxNoteLen]
	}
	if len(truncated) != mealFeedbackMaxNoteLen {
		t.Fatalf("truncated note length = %d, want %d", len(truncated), mealFeedbackMaxNoteLen)
	}
}
